podzadania.odpowiedz:
liczba_progow := 0;
for i := 1 to n-1 do
    if a[i] > a[i+1] then liczba_progow := liczba_progow + 1;

najw_liczba_progow := 0;
liczba_progow_w_schodach := 0;
for i := 1 to n-1 do
    if a[i] < a[i+1] then
    { a[i+1] moze byc poczatkiem nowych schodow }
    begin
        if liczba_progow_w_schodach > najw_liczba_progow then
            najw_liczba_progow := liczba_progow_w_schodach;
        liczba_progow_w_schodach := 0
    end
    else
        if a[i] > a[i+1] then
            liczba_progow_w_schodach := liczba_progow_w_schodach + 1;

if liczba_progow_w_schodach > najw_liczba_progow then
    najw_liczba_progow := liczba_progow_w_schodach;
